CREATE VIEW v_player_stats AS SELECT Player.id AS player_id, Player.player_api_id, Player.player_name, Player.birthday, Player.height, Player.weight, Player_Attributes.date AS attribute_date, Player_Attributes.overall_rating, Player_Attributes.potential, Player_Attributes.preferred_foot, Player_Attributes.attacking_work_rate, Player_Attributes.defensive_work_rate, Player_Attributes.crossing, Player_Attributes.finishing, Player_Attributes.heading_accuracy, Player_Attributes.short_passing, Player_Attributes.dribbling, Player_Attributes.free_kick_accuracy, Player_Attributes.ball_control, Player_Attributes.acceleration, Player_Attributes.sprint_speed, Player_Attributes.stamina, Player_Attributes.strength, Player_Attributes.penalties, Player.player_fifa_api_id, Player_Attributes.id, Player_Attributes.player_fifa_api_id AS Player_Attributes_player_fifa_api_id, Player_Attributes.player_api_id AS Player_Attributes_player_api_id, Player_Attributes.volleys, Player_Attributes.curve, Player_Attributes.jumping, Player_Attributes.long_shots FROM Player LEFT JOIN Player_Attributes ON Player.player_api_id = Player_Attributes.player_api_id;

CREATE VIEW v_team_stats AS SELECT Team.id AS team_id, Team.team_api_id, Team.team_long_name, Team.team_short_name, Team_Attributes.date AS attribute_date, Team_Attributes.buildUpPlaySpeed AS build_up_play_speed, Team_Attributes.buildUpPlayPassing AS build_up_play_passing, Team_Attributes.chanceCreationPassing AS chance_creation_passing, Team_Attributes.chanceCreationCrossing AS chance_creation_crossing, Team_Attributes.chanceCreationShooting AS chance_creation_shooting, Team_Attributes.defencePressure AS defence_pressure, Team_Attributes.defenceAggression AS defence_aggression, Team_Attributes.defenceTeamWidth AS defence_team_width, Team_Attributes.team_fifa_api_id, Team_Attributes.team_api_id AS Team_Attributes_team_api_id, Team_Attributes.buildUpPlaySpeedClass, Team_Attributes.buildUpPlayPassingClass, Team_Attributes.chanceCreationPassingClass, Team_Attributes.defenceAggressionClass FROM Team LEFT JOIN Team_Attributes ON Team.team_api_id = Team_Attributes.team_api_id;

CREATE VIEW v_match_details AS SELECT Match.id AS match_id, Match.season, Match.stage, Match.date AS match_date, Match.home_team_goal, Match.away_team_goal, League.name AS league_name, Country.name AS country_name, home_team.team_long_name AS home_team_name, away_team.team_long_name AS away_team_name, Match.country_id, Match.league_id, Match.away_team_api_id, League.id, Country.id AS Country_id_2, home_team.id AS home_team_id, home_team.team_api_id, home_team.team_short_name, away_team.id AS away_team_id, away_team.team_api_id AS away_team_team_api_id, away_team.team_short_name AS away_team_team_short_name FROM Match LEFT JOIN League ON Match.league_id = League.id LEFT JOIN Country ON Match.country_id = Country.id LEFT JOIN Team AS home_team ON Match.home_team_api_id = home_team.team_api_id LEFT JOIN Team AS away_team ON Match.away_team_api_id = away_team.team_api_id;
